import subprocess
import psutil
import time


def _process_iter():
    """Return the current processes, with the ``name`` attribute preloaded."""
    try:
        return list(psutil.process_iter(["name"]))
    except TypeError:
        # Older / mocked implementations that do not accept ``attrs``.
        return list(psutil.process_iter())


def _name_of(process):
    """Best-effort lookup of a process' name."""
    try:
        info = process.info
    except Exception:
        info = None

    if isinstance(info, dict):
        name = info.get("name")
        if name:
            return name

    try:
        return process.name()
    except Exception:
        return None


def _terminate(process):
    """Terminate a process and give it a chance to exit."""
    try:
        process.terminate()
    except (psutil.NoSuchProcess, psutil.AccessDenied, AttributeError):
        return

    try:
        process.wait(timeout=3)
    except TypeError:
        # ``wait`` does not support a timeout in some implementations.
        try:
            process.wait()
        except Exception:
            pass
    except psutil.TimeoutExpired:
        try:
            process.kill()
            process.wait()
        except Exception:
            pass
    except Exception:
        pass


def task_func(process_name: str) -> str:
    """Ensure *process_name* is running, restarting it when already present.

    If no running process is named *process_name* it is started.  If such a
    process already exists it is terminated first and then started again.

    Args:
        process_name: Name (and command) of the process.

    Returns:
        str: ``"Process not found. Starting <process_name>."`` when the
        process had to be started, or
        ``"Process found. Restarting <process_name>."`` when it was
        terminated and started again.
    """
    found = False

    for process in _process_iter():
        if _name_of(process) == process_name:
            found = True
            _terminate(process)
            break

    if found:
        # Give the operating system a moment to release the process slot
        # before the replacement is launched.
        time.sleep(0.1)
        subprocess.Popen([process_name])
        return f"Process found. Restarting {process_name}."

    subprocess.Popen([process_name])
    return f"Process not found. Starting {process_name}."
